import { type DataGridColumn, TreeGrid, type TreeGridRow } from '@design-schema/react';

const DATA: TreeGridRow[] = [
  {
    id: 'assets',
    name: 'Assets',
    balance: 128400,
    children: [
      { id: 'assets-cash', name: 'Cash', balance: 42000 },
      { id: 'assets-receivable', name: 'Accounts receivable', balance: 31400 },
      {
        id: 'assets-equipment',
        name: 'Equipment',
        balance: 55000,
        children: [
          { id: 'assets-equipment-office', name: 'Office equipment', balance: 20000 },
          { id: 'assets-equipment-vehicles', name: 'Vehicles', balance: 35000 },
        ],
      },
    ],
  },
  {
    id: 'liabilities',
    name: 'Liabilities',
    balance: 41200,
    children: [
      { id: 'liabilities-payable', name: 'Accounts payable', balance: 18200 },
      { id: 'liabilities-loans', name: 'Loans payable', balance: 23000 },
    ],
  },
  { id: 'equity', name: "Owner's equity", balance: 87200 },
];

const COLUMNS: DataGridColumn[] = [
  { key: 'name', header: 'Account', isRowHeader: true, width: 260 },
  {
    key: 'balance',
    header: 'Balance (USD)',
    abbr: 'Balance',
    align: 'end',
    width: 160,
    sortable: true,
    editable: true,
    editor: 'number',
    render: (row) => `$${(row.balance as number).toLocaleString()}`,
  },
];

<TreeGrid
  caption="Chart of accounts"
  columns={COLUMNS}
  data={DATA}
  defaultExpanded={['assets', 'liabilities']}
/>

snippets.lit:
import '@design-schema/lit';
import { html } from 'lit';
import type { TreeGridCellChangeDetail, TreeGridColumnResizeDetail, TreeGridExpandChangeDetail, TreeGridExpandDetail, TreeGridRow, TreeGridSelectionChangeDetail, TreeGridSortChangeDetail, DataGridColumn } from '@design-schema/lit';

const accountColumns: DataGridColumn[] = [
  { key: 'name', header: 'Account', isRowHeader: true, width: 220, resizable: true },
  { key: 'code', header: 'Code', width: 100 },
  {
    key: 'balance',
    header: 'Balance (USD)',
    align: 'end',
    sortable: true,
    editable: true,
    editor: 'number',
    width: 140,
  },
];

const accountsData: TreeGridRow[] = [
  {
    id: 'assets',
    name: 'Assets',
    code: '1000',
    balance: 125000,
    children: [
      {
        id: 'current-assets',
        name: 'Current assets',
        code: '1100',
        balance: 85000,
        children: [
          { id: 'cash', name: 'Cash', code: '1110', balance: 50000 },
          { id: 'receivables', name: 'Accounts receivable', code: '1120', balance: 35000 },
        ],
      },
      {
        id: 'fixed-assets',
        name: 'Fixed assets',
        code: '1200',
        balance: 40000,
        children: [{ id: 'equipment', name: 'Equipment', code: '1210', balance: 40000 }],
      },
    ],
  },
  {
    id: 'liabilities',
    name: 'Liabilities',
    code: '2000',
    balance: 42000,
    children: [{ id: 'payables', name: 'Accounts payable', code: '2100', balance: 42000 }],
  },
  {
    id: 'equity',
    name: 'Equity',
    code: '3000',
    balance: 83000,
    children: 'lazy',
  },
];

html`
    <ds-tree-grid
      caption="Chart of accounts"
      .columns=${accountColumns}
      .data=${accountsData}
      .defaultExpanded=${['assets', 'current-assets'] ?? []}
      @expand-change=${(event: CustomEvent<TreeGridExpandChangeDetail>) => console.log('expand-change', event.detail)}
      @expand=${(event: CustomEvent<TreeGridExpandDetail>) => console.log('expand', event.detail)}
      @sort-change=${(event: CustomEvent<TreeGridSortChangeDetail>) => console.log('sort-change', event.detail)}
      @selection-change=${(event: CustomEvent<TreeGridSelectionChangeDetail>) =>
  console.log('selection-change', event.detail)}
      @cell-change=${(event: CustomEvent<TreeGridCellChangeDetail>) => console.log('cell-change', event.detail)}
      @column-resize=${(event: CustomEvent<TreeGridColumnResizeDetail>) => console.log('column-resize', event.detail)}
    ></ds-tree-grid>
`;

